// 有限师承页绑定原身份、当面意愿与个人经历；不透出远方人物位置/生命/余额或控制授权。
#include "apprenticeship_views.hpp"
#include "apprenticeship_receipts.hpp"
#include "resident/views/common_presentation.hpp"
#include <algorithm>
namespace hanmo::resident {namespace {
using V=BoundaryValue;
V identity(const CommonStore& c){StableId world;const char* digits="0123456789abcdef";for(auto b:c.state().identity.world_id){world+=digits[b>>4];world+=digits[b&15];}const auto& i=c.state().identity;return boundary::obj({{"world_id",V{world}},{"execution_epoch",V{i.execution_epoch}},{"revision",V{i.revision}},{"tick",V{i.tick}}});}
V person(const CommonStore& c,const CommonCatalog& catalog,const StableId& actor){auto name=CommonPresentation(c.state(),catalog).display_name(actor);return boundary::obj({{"actor_id",V{actor}},{"name",V{name.ok?name.value:actor}}});}
// 对未获知拒绝/退出的一方只给普通可办理性，不泄露隐藏决定或死亡原因。
V operation(const CommonStore& c,const InteractionState& meeting,const InteractionCatalog& interaction,const InteractionAccess& contact,const ApprenticeshipCatalog& catalog,const FamilyApprenticeshipState& state,const ApprenticeshipIdentityRead& people,const ApprenticeshipCommand& command,bool detailed){auto quote=preview_apprenticeship_command(c,meeting,interaction,contact,catalog,state,people,c.state().metadata.player_actor_id,command);return boundary::obj({{"kind",V{command.kind}},{"params",encode_apprenticeship_command(command)},{"available",V{quote.ok}},{"code",V{quote.ok?StableId{}:detailed?quote.error.original.code:StableId{"ApprenticeshipUnavailable"}}}});}
V::Array slice(V::Array input,Integer page){const auto begin=std::min(input.size(),static_cast<std::size_t>(page)*16),end=std::min(input.size(),begin+16);return V::Array(input.begin()+begin,input.begin()+end);}
}
Outcome<BoundaryValue> query_apprenticeship_page(const CommonStore& c,const CommonCatalog& common,const InteractionState& meeting,const InteractionCatalog& interaction,const InteractionAccess& contact,const ApprenticeshipCatalog& catalog,const FamilyApprenticeshipState& state,const ApprenticeshipIdentityRead& people,Integer page){
    using namespace boundary;if(!catalog.enabled)return {false,{},common_failure("ApprenticeshipProfileRequired").error};if(page<0||page>4095)return {false,{},common_failure("InvalidApprenticeshipPage").error};auto history=validate_family_apprenticeship(c,interaction,catalog,state,people);if(!history.ok)return {false,{},history.error};auto valid=validate_apprenticeship_result_bindings(c,state);if(!valid.ok)return {false,{},valid.error};const auto& actor=c.state().metadata.player_actor_id;V::Array statements,proposals,bonds;
    for(const auto& row:catalog.statements.rows()){
        auto current=preview_apprenticeship_statement(c,meeting,interaction,contact,catalog,people,actor,row.first);if(!current.ok){if(current.error.kind!=ErrorKind::rule)return {false,{},current.error};continue;}
        ApprenticeshipCommand command;command.kind="family_apprenticeship_receive";command.statement_id=row.first;const auto& s=current.value.source;statements.push_back(obj({{"statement_id",V{row.first}},{"teacher",person(c,common,s.teacher_actor_id)},{"student",person(c,common,s.student_actor_id)},{"skill_id",V{s.skill_id}},{"operation",operation(c,meeting,interaction,contact,catalog,state,people,command,true)}}));
    }
    for(auto it=state.proposals.rows().rbegin();it!=state.proposals.rows().rend();++it){const auto& p=it->second.source;if(actor!=p.speaker_actor_id&&actor!=p.listener_actor_id)continue;StableId response;bool source_public=false;for(const auto& row:state.replies.rows())if(row.second.proposal_id==it->first&&(row.second.actor_id==actor||row.second.decision=="accepted")){response=row.second.decision;source_public=true;}
        V::Array operations;if(response.empty()){const auto choices=actor==p.listener_actor_id?std::vector<StableId>{"accepted","refused"}:std::vector<StableId>{"withdrawn"};for(const auto& choice:choices){ApprenticeshipCommand command;command.kind="family_apprenticeship_reply";command.proposal_id=it->first;command.decision=choice;operations.push_back(operation(c,meeting,interaction,contact,catalog,state,people,command,false));}}
        proposals.push_back(obj({{"proposal_id",V{it->first}},{"teacher",person(c,common,p.teacher_actor_id)},{"student",person(c,common,p.student_actor_id)},{"skill_id",V{p.skill_id}},{"received_tick",V{p.tick}},{"known_response",V{source_public?response:StableId{"not_known"}}},{"operations",V{std::move(operations)}}}));
    }
    for(auto it=history.value.bonds.rows().rbegin();it!=history.value.bonds.rows().rend();++it){const auto& b=it->second;if(actor!=b.teacher_actor_id&&actor!=b.student_actor_id)continue;StableId known_exit;Integer ended=-1;if(b.exit_fact_id){const auto* e=state.exits.find(*b.exit_fact_id);if(e&&e->actor_id==actor){known_exit=*b.exit_fact_id;ended=e->tick;}}
        V::Array operations;if(known_exit.empty()){ApprenticeshipCommand command;command.kind="family_apprenticeship_exit";command.bond_id=b.id;operations.push_back(operation(c,meeting,interaction,contact,catalog,state,people,command,false));}
        bonds.push_back(obj({{"bond_id",V{b.id}},{"teacher",person(c,common,b.teacher_actor_id)},{"student",person(c,common,b.student_actor_id)},{"skill_id",V{b.skill_id}},{"accepted_tick",V{b.accepted_tick}},{"known_exit_fact_id",V{known_exit}},{"known_exit_tick",V{ended}},{"operations",V{std::move(operations)}}}));
    }
    const Integer statement_count=statements.size(),proposal_count=proposals.size(),bond_count=bonds.size();return {true,obj({{"actor_id",V{actor}},{"source_identity",identity(c)},{"page",V{page}},{"page_size",V{Integer{16}}},{"statement_count",V{statement_count}},{"proposal_count",V{proposal_count}},{"bond_count",V{bond_count}},{"statements",V{slice(std::move(statements),page)}},{"proposals",V{slice(std::move(proposals),page)}},{"bonds",V{slice(std::move(bonds),page)}},{"explanation",V{"这里只记录本人真实师承经历。技艺仍须原课程实际学习；师承不转财产，不等于接受继任。未收到的远方决定不会自动显示。"}}}),{}};
}
Outcome<BoundaryValue> query_apprenticeship_courses_page(const CommonStore& c,const GrowthState& growth,const FamilyApprenticeshipState& state,const StableId& bond,Integer page){
    auto read=read_apprenticeship_courses(c,growth,state,c.state().metadata.player_actor_id,bond,page);if(!read.ok)return {false,{},read.error};const auto& p=read.value;V::Array rows;for(const auto& r:p.rows)rows.push_back(boundary::obj({{"study_fact_id",V{r.study_fact_id}},{"phase",V{r.phase}},{"code",V{r.code}},{"start_tick",V{r.start_tick}},{"completed_tick",V{r.completed_tick}},{"actual_lessons",V{r.actual_lessons}},{"credited_xp",V{r.credited_xp}}}));return {true,boundary::obj({{"actor_id",V{p.observer_actor_id}},{"source_identity",identity(c)},{"bond_id",V{p.bond_id}},{"teacher_actor_id",V{p.teacher_actor_id}},{"student_actor_id",V{p.student_actor_id}},{"skill_id",V{p.skill_id}},{"page",V{page}},{"page_size",V{Integer{16}}},{"total",V{p.total}},{"rows",V{std::move(rows)}},{"explanation",V{"仅列这项师承有效时真正开工的原课程。退出不删除已学成果或已付课程；未结算的预计经验不计入已得。"}}}),{}};
}
}
